// ── Helpers ──────────────────────────────────────────────────────────────────
function carGetMakes() {
  return [...new Set(CAR_MODELS_DATA.map(r => r.make))].sort();
}
function carGetModels(make) {
  return [...new Set(
    CAR_MODELS_DATA.filter(r => r.make === make).map(r => r.model)
  )].sort();
}
function carGetModelNumbers(make, model) {
  return CAR_MODELS_DATA
    .filter(r => r.make === make && r.model === model && r.modelNumber)
    .map(r => r.modelNumber);
}
function carGetBodyType(make, model) {
  const entry = CAR_MODELS_DATA.find(r => r.make === make && r.model === model);
  return entry ? entry.bodyType : '';
}
